 m=re.search(r'const common\\s*=\\s*`([\\s\\S]*?)`;',code);common=m.group(1)\n  for n in ['b','c']:\n   m=re.search(r'const '+n+r'=common\\+`([\\s\\S]*?)`;',code)\n   if m:(out/f'prompt-{n}.txt').write_text(common+m.group(1)+'\\n')\n if 'store(\"atlas_common\"' in code:\n  common=re.search(r'const common\\s*=\\s*`([\\s\\S]*?)`;',code).group(1)\n  for m in re.finditer(r'\\[\"([0-9]+-[^\"]+)\",`([\\s\\S]*?)`,\\[',code):(out/f'prompt-{m.group(1)}.txt').write_text(common+'\\n'+m.group(2)+'\\n')\ngen=Path('/home/andrew/.codex/generated_images/01a0e573-1ef4-7012-b126-a44152e43072');(out/'images').mkdir(exist_ok=True)\nitems={'style-a':'exec-a453f7ed-b88e-4272-b573-4c7e8d272eeb.png','style-b':'exec-ee116a78-d996-4fbe-b379-4dc3aee0e477.png','style-c':'exec-8b28c9b9-de0e-424b-903a-d257efc05927.png','01-regions':'exec-ca31e039-a67e-478a-8861-0146c9934d62.png','02-ball-culture':'exec-cd19bf4f-be8c-45a4-8d93-5c24a9dfdc2e.png','03-pilots':'exec-5cc08c60-c946-4297-8cba-446de7844d85.png'}\nrows=[]\nfor name,src in items.items():\n dest=out/'images'/f'{name}.png';shutil.copy2(gen/src,dest);rows.append({'image':str(dest.relative_to(out)),'source':str(gen/src),'sha256':hashlib.sha256(dest.read_bytes()).hexdigest(),'provider':'built-in imagegen','status':'owner-selected treatment' if name=='style-a' else 'candidate concept'})\n(out/'image-manifest.json').write_text(json.dumps({'images':rows},indent=2)+'\\n')\n(out/'owner-choice.json').write_text(json.dumps({'owner_quote':'I really like style A','selected_treatment':'A','scope':'render treatment; exact geometry and mechanics remain subject to design contracts'},indent=2)+'\\n')\nprint('Restored',count,'documents,',len(requests),'prompt records and',len(rows),'images.')\nPY","max_output_tokens":1000}));
